// 取得分類
export const PLAYER_CATEGORIES = ['男子', '女子', '混雙', '亞洲'] as const;

export const getPlayerBySlug = (slug: string): Player | undefined =>
  PLAYERS.find(p => p.slug === slug);

export const getFeaturedPlayers = (): Player[] =>
  PLAYERS.filter(p => p.featured);

export const getPlayersByCategory = (cat: PlayerCategory): Player[] =>
  PLAYERS.filter(p => p.category === cat);

export const getAsianPlayers = (): Player[] =>
  PLAYERS.filter(p => p.isAsian);
